def get_action_name_from_msst_to_vp3d(action_idx, subaction_idx, subject_id):
    """Map action indices to npz action names (from extract_h36m_simple.py)"""
    s_id = f'S{subject_id}'

    if action_idx - 2 < 0 or action_idx - 2 >= len(MSST_ACTION_NAMES):
        return None

    action_name = MSST_ACTION_NAMES[action_idx - 2]
    key = (action_name, subaction_idx)

    if s_id in MSST_STATIC_ACTION_MAP and key in MSST_STATIC_ACTION_MAP[s_id]:
        return MSST_STATIC_ACTION_MAP[s_id][key]

    return None